import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../core/app_controller.dart';
import '../widgets/common.dart';

class ReportsScreen extends StatelessWidget { const ReportsScreen({super.key}); @override Widget build(BuildContext context){final app=context.watch<AppController>(); final success=app.operations.where((e)=>e['status']=='success').length; final failed=app.operations.where((e)=>e['status']=='failed').length; return Scaffold(appBar:AppBar(title:const Text('التقارير والإحصائيات')),body:RefreshIndicator(onRefresh:app.refreshWalletAndReports,child:ListView(padding:const EdgeInsets.all(12),children:[Row(children:[Expanded(child:_stat('العمليات','${app.operations.length}',AppColors.blue,Icons.receipt_long)),const SizedBox(width:8),Expanded(child:_stat('ناجحة','$success',Colors.green,Icons.check_circle)),const SizedBox(width:8),Expanded(child:_stat('فاشلة','$failed',Colors.red,Icons.error_outline))]),const SizedBox(height:10),PageCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('ملخص الخادم',textAlign:TextAlign.right,style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('الرصيد الحالي: ${app.walletBalance.toStringAsFixed(2)} ر.ي',style:const TextStyle(fontWeight:FontWeight.w800)),Text('عدد المنتجات: ${app.products.length}',style:const TextStyle(fontSize:11)),Text('عدد المتاجر: ${app.vendors.length}',style:const TextStyle(fontSize:11)),Text('عدد الطلبات: ${app.orders.length}',style:const TextStyle(fontSize:11)),]))]));}}
Widget _stat(String title,String value,Color color,IconData icon)=>Container(padding:const EdgeInsets.all(11),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(15),border:Border.all(color:const Color(0xFFE2E8F0))),child:Column(children:[Icon(icon,color:color,size:20),const SizedBox(height:5),Text(value,style:TextStyle(fontSize:18,fontWeight:FontWeight.w900,color:color)),Text(title,style:const TextStyle(fontSize:9,color:Colors.black54))]));
